const regimeData = $('Fetch Today\'s Regime Summary').first().json;
const moversData = $('Fetch Top Movers').all();

const now = new Date();
const dateStr = now.toLocaleDateString('en-IN', { weekday: 'long', year: 'numeric', month: 'long', day: 'numeric' });

const regimeEmoji = { 'BULL': '🐂', 'BEAR': '🐻', 'HIGH_VOLATILITY': '⚡', 'SIDEWAYS': '↔️' };
const regime = regimeData?.regime_label || 'UNKNOWN';
const emoji = regimeEmoji[regime] || '📊';
const confidence = regimeData?.confidence_score ? (parseFloat(regimeData.confidence_score) * 100).toFixed(1) : 'N/A';
const volatility = regimeData?.volatility_level || 'N/A';
const assets = regimeData?.assets_analyzed || 'N/A';

let moversText = '';
let moversHtml = '<table border="1" cellpadding="6" cellspacing="0" style="border-collapse:collapse;width:100%;font-family:monospace;"><tr style="background:#1a1a2e;color:#e0e0e0;"><th>Ticker</th><th>Company</th><th>Sector</th><th>Close</th><th>RSI</th><th>Return</th></tr>';

for (const item of moversData) {
  const d = item.json;
  const sign = parseFloat(d.daily_return_pct) >= 0 ? '+' : '';
  const arrow = parseFloat(d.daily_return_pct) >= 0 ? '↑' : '↓';
  moversText += `\n  ${arrow} ${d.ticker_symbol} (${d.asset_name}) | Close: ₹${parseFloat(d.close_price).toFixed(2)} | RSI: ${parseFloat(d.rsi).toFixed(1)} | Return: ${sign}${d.daily_return_pct}%`;
  const color = parseFloat(d.daily_return_pct) >= 0 ? 'green' : 'red';
  moversHtml += `<tr><td><b>${d.ticker_symbol}</b></td><td>${d.asset_name}</td><td>${d.sector || 'N/A'}</td><td>₹${parseFloat(d.close_price).toFixed(2)}</td><td>${parseFloat(d.rsi).toFixed(1)}</td><td style="color:${color}">${sign}${d.daily_return_pct}%</td></tr>`;
}
moversHtml += '</table>';

const telegramMessage = `📈 *QuantCopilot AI — Daily Market Report*\n🗓 ${dateStr}\n━━━━━━━━━━━━━━━━━━━━━\n${emoji} *Market Regime:* ${regime}\n📊 *Confidence:* ${confidence}%\n🌊 *Volatility:* ${volatility}\n🏢 *Assets Analyzed:* ${assets}\n━━━━━━━━━━━━━━━━━━━━━\n🔥 *Top Movers Today:*${moversText}\n━━━━━━━━━━━━━━━━━━━━━\n⚡ Powered by QuantCopilot AI`;

const regimeCssClass = regime === 'BULL' ? 'bull' : regime === 'BEAR' ? 'bear' : regime === 'HIGH_VOLATILITY' ? 'highvol' : 'sideways';

const emailHtml = `<!DOCTYPE html><html><head><style>body{font-family:'Segoe UI',Arial,sans-serif;background:#0d0d1a;color:#e0e0e0;margin:0;padding:20px}.container{max-width:700px;margin:0 auto;background:#1a1a2e;border-radius:12px;padding:30px}h1{color:#00d4ff;font-size:24px;border-bottom:2px solid #00d4ff;padding-bottom:10px}.badge{display:inline-block;padding:6px 16px;border-radius:20px;font-weight:bold;font-size:16px}.bull{background:#004d00;color:#00ff88}.bear{background:#4d0000;color:#ff4444}.highvol{background:#4d3300;color:#ffaa00}.sideways{background:#1a1a4d;color:#8888ff}.metric{background:#0d0d2e;border-radius:8px;padding:12px 20px;margin:8px 0}.metric-label{color:#888;font-size:12px;text-transform:uppercase}.metric-value{font-size:22px;font-weight:bold;color:#00d4ff}.footer{margin-top:20px;text-align:center;color:#555;font-size:12px}</style></head><body><div class="container"><h1>📈 QuantCopilot AI — Daily Report</h1><p style="color:#888">🗓 ${dateStr}</p><div class="metric"><div class="metric-label">Market Regime</div><span class="badge ${regimeCssClass}">${emoji} ${regime}</span></div><div class="metric"><div class="metric-label">Model Confidence</div><div class="metric-value">${confidence}%</div></div><div class="metric"><div class="metric-label">Volatility Level</div><div class="metric-value">${volatility}</div></div><div class="metric"><div class="metric-label">Assets Analyzed</div><div class="metric-value">${assets}</div></div><h2 style="color:#00d4ff;margin-top:24px">🔥 Top Movers</h2>${moversHtml}<div class="footer">Powered by QuantCopilot AI &bull; KMeans Regime Detection v2.0</div></div></body></html>`;

return [{ json: { telegram_message: telegramMessage, email_html: emailHtml, email_subject: `QuantCopilot AI Report — ${regime} Regime | ${dateStr}`, regime, confidence, date: dateStr } }];

const items = $input.all();

if (!items || items.length === 0) {
  return [{ json: { has_alerts: false, message: '', count: 0 } }];
}

const now = new Date();
const dateStr = now.toLocaleDateString('en-IN', { year: 'numeric', month: 'short', day: 'numeric' });

const oversold = items.filter(i => i.json.rsi_signal === 'OVERSOLD');
const overbought = items.filter(i => i.json.rsi_signal === 'OVERBOUGHT');

let msg = `🔔 *QuantCopilot AI — RSI Extreme Alert*\n🗓 ${dateStr}\n━━━━━━━━━━━━━━━━━━━━━`;

if (oversold.length > 0) {
  msg += `\n\n📉 *OVERSOLD (RSI < 30):*`;
  for (const item of oversold) {
    const d = item.json;
    msg += `\n  🟢 *${d.ticker_symbol}* — RSI: ${d.rsi} | ₹${d.close_price} | ${d.daily_return_pct}%`;
  }
}

if (overbought.length > 0) {
  msg += `\n\n📈 *OVERBOUGHT (RSI > 70):*`;
  for (const item of overbought) {
    const d = item.json;
    msg += `\n  🔴 *${d.ticker_symbol}* — RSI: ${d.rsi} | ₹${d.close_price} | ${d.daily_return_pct}%`;
  }
}

msg += `\n━━━━━━━━━━━━━━━━━━━━━\n⚡ QuantCopilot AI | ${items.length} alerts`;

return [{ json: { has_alerts: true, message: msg, count: items.length, oversold_count: oversold.length, overbought_count: overbought.length } }];

const d = $input.first().json;

const issues = [];

if (parseInt(d.total_assets) === 0) issues.push('No market assets found in database');
if (parseInt(d.total_price_records) < 100) issues.push(`Low price records: only ${d.total_price_records} rows`);
if (parseInt(d.total_indicator_records) < 100) issues.push(`Low indicator records: only ${d.total_indicator_records} rows`);
if (parseInt(d.total_regime_records) === 0) issues.push('No regime records found — model may not have run');
if (String(d.data_is_fresh) === 'false') issues.push(`Data may be stale — latest: ${d.latest_price_date}`);

const isHealthy = issues.length === 0;

const summary = `DB Health Check — ${new Date().toISOString()}\n\nAssets: ${d.total_assets}\nPrice Records: ${d.total_price_records}\nIndicator Records: ${d.total_indicator_records}\nRegime Records: ${d.total_regime_records}\nLatest Price: ${d.latest_price_date}\nLatest Regime: ${d.latest_regime_date}\nFresh Data: ${d.data_is_fresh}\n\n${isHealthy ? 'Database is HEALTHY' : 'Issues:\n' + issues.join('\n')}`;

return [{ json: { is_healthy: isHealthy, issue_count: issues.length, issues, summary, stats: d } }];
